import React, { useEffect, useState } from "react";
import Slider from "react-slick"; // react-slick 라이브러리 임포트
import { getDailyBoxOffice, getMovieDetail } from "../api/boxofficeApi"; // API 경로 확인
import { getPosterFromTMDB } from "../api/tmdbApi"; // API 경로 확인
import MovieCard from "../components/MovieCard"; // MovieCard 경로 확인

// react-slick 필수 CSS 임포트
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchBoxOffice = async () => {
      setLoading(true);
      setError(null);
      try {
        const today = new Date();
        today.setDate(today.getDate() - 1); // 어제 날짜
        const targetDt = `${today.getFullYear()}${String(
          today.getMonth() + 1
        ).padStart(2, "0")}${String(today.getDate()).padStart(2, "0")}`;
        
        const boxOfficeList = await getDailyBoxOffice(targetDt);

        const enrichedMovies = await Promise.all(
          boxOfficeList.map(async (movie, index) => {
            const detail = await getMovieDetail(movie.movieCd);
            const year = detail.openDt?.substring(0, 4) || "";
            const posterUrl = await getPosterFromTMDB(movie.movieNm, year, {
              movieNmEn: detail.movieNmEn,
              nation: detail.nations?.[0]?.nationNm,
            });

            // MovieCard에 필요한 모든 데이터를 구조화하여 전달
            return {
              id: movie.movieCd,
              rank: movie.rank, // KOFIC에서 제공하는 순위 사용
              title: movie.movieNm,
              englishTitle: detail.movieNmEn || "",
              posterPath: posterUrl || "https://via.placeholder.com/400x600?text=No+Image",
              summary: `예매율 ${movie.salesShare}% | 누적 ${parseInt(movie.audiAcc).toLocaleString()}명`,
              details: {
                "개봉일": detail.openDt ? detail.openDt.replace(/(\d{4})(\d{2})(\d{2})/, '$1.$2.$3') : "N/A",
                "감독": detail.directors?.[0]?.peopleNm || "N/A",
                "출연": detail.actors?.slice(0, 3).map(a => a.peopleNm).join(', ') + (detail.actors?.length > 3 ? '...' : ''),
                "장르": detail.genres?.map(g => g.genreNm).join(', ') || "N/A",
                "상영 시간": `${detail.showTm || "N/A"}분`,
              },
            };
          })
        );
        setMovies(enrichedMovies);
      } catch (err) {
        console.error("박스오피스 데이터를 불러오는 데 실패했습니다:", err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };
    fetchBoxOffice();
  }, []);

  const sliderSettings = {
    className: "center",
    centerMode: true,
    infinite: true,
    centerPadding: "60px",
    slidesToShow: 5, // 중앙 포함 5개 표시
    speed: 500,
    arrows: true,
    responsive: [ // 화면 크기에 따른 반응형 설정
      {
        breakpoint: 1024,
        settings: { slidesToShow: 3, centerPadding: "40px" }
      },
      {
        breakpoint: 600,
        settings: { slidesToShow: 1, centerPadding: "40px" }
      }
    ]
  };

  if (loading) return <div className="page-message">로딩 중...</div>;
  if (error) return <div className="page-message">에러: {error}</div>;

  return (
    <div className="homepage-container">
      <h1 className="page-title">박스오피스</h1>
      <div className="box-office-carousel">
        <Slider {...sliderSettings}>
          {movies.map((movie) => (
            <MovieCard key={movie.id} movie={movie} />
          ))}
        </Slider>
      </div>
    </div>
  );
}

export default HomePage;
